import React from 'react';
import { Marker, Popup, TileLayer, useMap } from 'react-leaflet';
import L from 'leaflet';

const MapComponent = ({ vehicles, stations }) => {
  const map = useMap();

  return (
    <>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      />
      {vehicles.map((vehicle, index) => (
        <Marker
          key={index}
          position={vehicle.location}
          icon={L.icon({
            iconUrl: 'path/to/vehicle-icon.png', // Remplacez par le chemin vers votre icône de véhicule
            iconSize: [25, 41],
            iconAnchor: [12, 41],
            popupAnchor: [1, -34],
            shadowSize: [41, 41],
          })}
        >
          <Popup>
            <b>{vehicle.name}</b><br />
            Battery: {vehicle.battery_capacity} kWh
          </Popup>
        </Marker>
      ))}
      {stations.map((station, index) => (
        <Marker
          key={index}
          position={station.location}
          icon={L.icon({
            iconUrl: 'path/to/station-icon.png', // Remplacez par le chemin vers votre icône de station
            iconSize: [25, 41],
            iconAnchor: [12, 41],
            popupAnchor: [1, -34],
            shadowSize: [41, 41],
          })}
        >
          <Popup>
            <b>{station.name}</b><br />
            Charging Speed: {station.charging_speed} kW
          </Popup>
        </Marker>
      ))}
    </>
  );
};

export default MapComponent;
